(async () => {
    const button = (text, root = document) => [...root.querySelectorAll('button')].find((x) => x.textContent.trim() === text)
    const on = button('Turn the WNBA on')
    if (!on) return 'NO BUTTON'
    const t0 = Date.now()
    on.click()
    const started = await until(async () => (await window.api.stats.status('wnba')).busy, 60000)
    const done = await until(async () => { const s = await window.api.stats.status('wnba'); return !s.busy && s.available }, 40 * 60000)
    const s = await window.api.stats.status('wnba')
